{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_warehouse_and_alloc_tagged AS WITH alloc_ref_dates AS ( SELECT DISTINCT order_date, DATEADD(\'day\', -1, order_date) AS reference_date FROM snitch_db.maplemonk.fresh_actual_allocation ), wh_daily AS ( SELECT ar.order_date, CASE WHEN UPPER(w.FACILITY) LIKE \'%NORTH%\' OR UPPER(w.FACILITY) LIKE \'%TAURU%\' THEN \'NORTH\' ELSE \'SOUTH\' END AS wh_zone, UPPER(SUBSTRING(w.ITEM_SKUCODE, 1, LENGTH(w.ITEM_SKUCODE) - LENGTH(SPLIT_PART(w.ITEM_SKUCODE, \'-\', -1)) - 1)) AS sku_group, UPPER(SPLIT_PART(w.ITEM_SKUCODE, \'-\', -1)) AS size_code, COALESCE(w.INVENTORY, 0) AS usable_qty FROM alloc_ref_dates ar INNER JOIN snitch_db.maplemonk.WH_CLOSING_INV_DAILY_BASE w ON w.SNAPSHOT_DATE = ar.reference_date ), wh_options AS ( SELECT order_date, wh_zone, sku_group, SUM(usable_qty) AS avail_qty FROM wh_daily GROUP BY 1,2,3 ), wh_agg AS ( SELECT w.order_date, w.wh_zone, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, COUNT(DISTINCT w.sku_group) AS wh_full_size_options, SUM(w.avail_qty) AS wh_total_qty FROM wh_options w LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(w.sku_group) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), shipped_alloc AS ( SELECT a.branch_code::VARCHAR AS branch_code, a.order_date, ms.category, COALESCE(UPPER(ms.style), \'SNITCH\') AS style, COALESCE(UPPER(ms.meta1), \'N/A\') AS meta1, COALESCE(UPPER(ms.meta2), \'N/A\') AS meta2, COALESCE(UPPER(ms.meta3), \'N/A\') AS meta3, COUNT(DISTINCT a.sku_group) AS shipped_options, SUM(a.actual_qty) AS shipped_qty FROM snitch_db.maplemonk.fresh_actual_allocation a LEFT JOIN snitch_db.maplemonk.metafields_std ms ON UPPER(a.sku_group) = UPPER(ms.sku_group) WHERE ms.category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ) SELECT b.branch_code, b.order_date, b.category, b.style, b.meta1, b.meta2, b.meta3, b.ideal_mix_pct, b.pre_inv_units, b.pre_inv_mix_pct, b.pre_gap_pct, COALESCE(s.shipped_options, 0) AS shipped_options, COALESCE(s.shipped_qty, 0) AS shipped_qty, COALESCE(w.wh_full_size_options, 0) AS wh_full_size_options, COALESCE(w.wh_total_qty, 0) AS wh_total_qty, CASE WHEN b.pre_gap_pct > 0.02 AND COALESCE(w.wh_full_size_options, 0) = 0 THEN 1 ELSE 0 END AS wh_constraint_flag FROM snitch_db.maplemonk.fresh_store_pre_baseline b LEFT JOIN shipped_alloc s ON b.branch_code = s.branch_code AND b.order_date = s.order_date AND b.category = s.category AND b.style = s.style AND b.meta1 = s.meta1 AND b.meta2 = s.meta2 AND b.meta3 = s.meta3 LEFT JOIN snitch_db.maplemonk.store_meta_master_setup sm ON b.branch_code = sm.branch_code LEFT JOIN wh_agg w ON w.order_date = b.order_date AND w.wh_zone = COALESCE(sm.zone, \'SOUTH\') AND w.category = b.category AND w.style = b.style AND w.meta1 = b.meta1 AND w.meta2 = b.meta2 AND w.meta3 = b.meta3;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            